function clipLabel(definition,clip){const source=definition.assetId==='hooded-goblin'?GOBLIN_MOTIONS:definition.assetId==='elena'?ELENA_SPELLS:BOSS_MOTIONS;return source.find(m=>m.name===clip)?.label??(/idle|prayer/i.test(clip)?'서 있기':/sneak/i.test(clip)?'조심스럽게 걷기':/walk/i.test(clip)?'걷기':/run/i.test(clip)?'달리기':/hit/i.test(clip)?'피격':/death|dead|down/i.test(clip)?'쓰러지기':/stand/i.test(clip)?'일어나기':/slam/i.test(clip)?'내려치기':/alternate/i.test(clip)?'교차 시전':/cast/i.test(clip)?'마법 시전':'동작 '+(Object.values(definition.animation).indexOf(clip)+1));}
